module AES_CCHPC_Pipeline #(parameter security_order = 2) (plaintext, key, clk, rst, r, ciphertext, done);
    parameter integer d = security_order+1;
    parameter integer nonlinear_count = 680;

    input  [128*((2*(d-1))+1)-1:0] plaintext;
    input  [128*((2*(d-1))+1)-1:0] key;
    input  clk;
    input  rst;
    input  [nonlinear_count*((d-1)*d)-1:0] r;
    output [128*((2*(d-1))+1)-1:0] ciphertext;
    output [d-1:0] done;

    wire [2*(d-1):0] in_plaintext [127:0];
    wire [2*(d-1):0] in_key [127:0];
    wire [2*(d-1):0] out_ciphertext [127:0][1:0];

    wire [(d-1)*d-1:0] in_r  [nonlinear_count-1:0];
    wire [(d-1)*d-1:0] in_r0 [nonlinear_count-1:0]; // randomness round instance 0
    wire [(d-1)*d-1:0] in_r1 [nonlinear_count-1:0]; // randomness round instance 1

    // core control
    wire [d-2:0] prch0;
    wire [d-2:0] prch1;
    wire [d-2:0] prch_sel0;
    wire [d-2:0] prch_sel1;
    wire [((d-1)*d)-1:0] sel0;
    wire [((d-1)*d)-1:0] sel1;
    wire [2*(d-1):0] sel;
    wire cnt_rst;
    wire done_layer0;

    wire [5:0] Rcon;
    wire [2*d-2:0] Rcon_vec [5:0][0:1];
    assign Rcon_vec[0][0][0] = Rcon[0];
    assign Rcon_vec[1][0][0] = Rcon[1];
    assign Rcon_vec[2][0][0] = Rcon[2];
    assign Rcon_vec[3][0][0] = Rcon[3];
    assign Rcon_vec[4][0][0] = Rcon[4];
    assign Rcon_vec[5][0][0] = Rcon[5];
    assign Rcon_vec[0][1][0] = Rcon_vec[0][0][0];
    assign Rcon_vec[1][1][0] = Rcon_vec[1][0][0];
    assign Rcon_vec[2][1][0] = Rcon_vec[2][0][0];
    assign Rcon_vec[3][1][0] = Rcon_vec[3][0][0];
    assign Rcon_vec[4][1][0] = Rcon_vec[4][0][0];
    assign Rcon_vec[5][1][0] = Rcon_vec[5][0][0];

    wire n322;
    wire n323;
    wire n324;
    wire n325;
    wire n326;
    wire n327;
    wire n328;
    wire n329;
    wire n330;
    wire n331;
    wire n332;
    wire n333;
    wire n334;
    wire n335;
    wire n336;
    wire n337;
    wire n338;
    wire n339;

    wire [2*d-2:0] n283_vec [0:1];
    assign n283_vec[0][0] = n283;
    assign n283_vec[1][0] = n283_vec[0][0];

    wire [2*d-2:0] n285_vec [0:1];
    assign n285_vec[0][0] = n285;
    assign n285_vec[1][0] = n285_vec[0][0];

    wire [2*d-2:0] n321_vec;

    // io index mapping
    genvar i, j, k;
    generate
        for (i = 0; i < 128; i=i+1) begin : loop_assign_a_z_
            
            // input
            assign in_plaintext[i] = plaintext[(i+1)*(2*(d-1)+1)-1:i*(2*(d-1)+1)];
            assign in_key[i]       = key[(i+1)*(2*(d-1)+1)-1:i*(2*(d-1)+1)];

            // output
            assign ciphertext[(i+1)*(2*(d-1)+1)-1:i*(2*(d-1)+1)] = out_ciphertext[i][0];

        end

        // randomness ----------------------------------------------------------------------------------------------------------------
        // In this implementation, we make sure that fresh randomness is applied in proper dual-rail state internally via registers

        for (j = 0; j < (d-1); j=j+1) begin : loop_gen_sel_r_layer_

            for (i = 0; i < (j+1); i=i+1) begin : loop_gen_sel_r_precomp_
            
                // pre-charge signals for randomness
                assign sel0[j*(j+1)+2*i+1:j*(j+1)+2*i] = {2{prch_sel0[i]}};
                assign sel1[j*(j+1)+2*i+1:j*(j+1)+2*i] = {2{prch_sel1[i]}};

            end
        end

        for (j = 0; j < nonlinear_count; j=j+1) begin : loop_gen_r_idx_

            for (i = 0; i < ((d-1)*d); i=i+1) begin : loop_gen_r_rail_

                // fresh randomness registers
                REG_r reg_in_r_inst  (.clk(clk), .rst(rst),     .d(r[j*((d-1)*d)+i]), .q( in_r[j][i]));
                REG_r reg_in_r0_inst (.clk(clk), .rst(sel0[i]), .d(r[j*((d-1)*d)+i]), .q(in_r0[j][i]));
                REG_r reg_in_r1_inst (.clk(clk), .rst(sel1[i]), .d(r[j*((d-1)*d)+i]), .q(in_r1[j][i]));

            end
        end

        //-----------------------------------------------------------------------------------------------------------

        for (i=0; i < (d-1); i=i+1) begin : loop_gen_single_to_dual_rail_

            assign n283_vec[0][2*i+1] = 1'b0;
            assign n283_vec[1][2*i+1] = 1'b0;
            assign n285_vec[0][2*i+1] = 1'b0;
            assign n285_vec[1][2*i+1] = 1'b0;

            assign n283_vec[0][2*i+2] = prch0[i];
            assign n283_vec[1][2*i+2] = prch1[i];
            assign n285_vec[0][2*i+2] = prch0[i];
            assign n285_vec[1][2*i+2] = prch1[i];

            assign Rcon_vec[0][0][2*i+1] = 1'b0;
            assign Rcon_vec[1][0][2*i+1] = 1'b0;
            assign Rcon_vec[2][0][2*i+1] = 1'b0;
            assign Rcon_vec[3][0][2*i+1] = 1'b0;
            assign Rcon_vec[4][0][2*i+1] = 1'b0;
            assign Rcon_vec[5][0][2*i+1] = 1'b0;
            assign Rcon_vec[0][1][2*i+1] = 1'b0;
            assign Rcon_vec[1][1][2*i+1] = 1'b0;
            assign Rcon_vec[2][1][2*i+1] = 1'b0;
            assign Rcon_vec[3][1][2*i+1] = 1'b0;
            assign Rcon_vec[4][1][2*i+1] = 1'b0;
            assign Rcon_vec[5][1][2*i+1] = 1'b0;
            
            assign Rcon_vec[0][0][2*i+2] = prch0[i];
            assign Rcon_vec[1][0][2*i+2] = prch0[i];
            assign Rcon_vec[2][0][2*i+2] = prch0[i];
            assign Rcon_vec[3][0][2*i+2] = prch0[i];
            assign Rcon_vec[4][0][2*i+2] = prch0[i];
            assign Rcon_vec[5][0][2*i+2] = prch0[i];
            assign Rcon_vec[0][1][2*i+2] = prch1[i];
            assign Rcon_vec[1][1][2*i+2] = prch1[i];
            assign Rcon_vec[2][1][2*i+2] = prch1[i];
            assign Rcon_vec[3][1][2*i+2] = prch1[i];
            assign Rcon_vec[4][1][2*i+2] = prch1[i];
            assign Rcon_vec[5][1][2*i+2] = prch1[i];

        end

    endgenerate
    
    precharger_reg_CCHPC #(.security_order(security_order)) precharger_reg_inst (.clk(clk), .rst(rst), .prch(prch1), .a(n321), .z(n321_vec)); // primary input select
    controller_CCHPC #(.security_order(security_order)) controllerInst (.clk(clk), .rst(rst), .done_layer0(done_layer0), .done(done), .prch0(prch0), .prch1(prch1), .prch_sel0(prch_sel0), .prch_sel1(prch_sel1), .sel(sel), .cnt_rst(cnt_rst));

    wire [2*(d-1):0] RoundReg_Inst_ff_SDE_0_next_state [1:0];
    wire [2*(d-1):0] RoundReg_Inst_ff_SDE_1_next_state [1:0];
    wire [2*(d-1):0] RoundReg_Inst_ff_SDE_2_next_state [1:0];
    wire [2*(d-1):0] RoundReg_Inst_ff_SDE_3_next_state [1:0];
