    wire [2*(d-1):0] RoundReg_Inst_ff_SDE_10_next_state [1:0];
    wire [2*(d-1):0] RoundReg_Inst_ff_SDE_11_next_state [1:0];
    wire [2*(d-1):0] RoundReg_Inst_ff_SDE_12_next_state [1:0];
    wire [2*(d-1):0] RoundReg_Inst_ff_SDE_13_next_state [1:0];
    wire [2*(d-1):0] RoundReg_Inst_ff_SDE_14_next_state [1:0];
    wire [2*(d-1):0] RoundReg_Inst_ff_SDE_15_next_state [1:0];
    wire [2*(d-1):0] RoundReg_Inst_ff_SDE_16_next_state [1:0];
    wire [2*(d-1):0] RoundReg_Inst_ff_SDE_17_next_state [1:0];
    wire [2*(d-1):0] RoundReg_Inst_ff_SDE_18_next_state [1:0];
